INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Mikroprozessor immer nur eine Aufgabe gleichzeitig ausführt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Multitasking möglich"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich einen Mikroprozessor für ein IT-System auswähle?', 3, '[{"text": "Rechenleistung", "correct": true, "because": "Bestimmt Geschwindigkeit"}, {"text": "Schnellste Installation", "correct": false, "because": "Leistung zählt"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten gehören zu einem Mikroprozessor?', 5, '[{"text": "Rechenwerk", "correct": true, "because": "Führt Berechnungen aus"}, {"text": "Steuerwerk", "correct": true, "because": "Koordiniert Abläufe"}, {"text": "Büromöbel", "correct": false, "because": "Kein Bestandteil"}, {"text": "Monitor", "correct": false, "because": "Externes Gerät"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Mikroprozessor enthält Register. b) Er ist immer unabhängig von RAM.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "RAM wird benötigt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich einen Mikroprozessor für ein IT-System auswähle?', 4, '[{"text": "Taktfrequenz", "correct": false, "because": "Bestimmt Leistung"}, {"text": "Kernanzahl", "correct": false, "because": "Beeinflusst Multitasking"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Mikroprozessor ohne Cache nutzlos ist?', 2, '[{"text": "Nein", "correct": true, "because": "Cache optional"}, {"text": "Ja", "correct": false, "because": "Funktioniert ohne Cache"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich, wenn ich einen Mikroprozessor für ein System auswähle?', 3, '[{"text": "Hohe Leistung", "correct": true, "because": "Sichert Effizienz"}, {"text": "Schnellste Montage", "correct": false, "because": "Leistung wichtiger"}, {"text": "Weniger Kerne", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind bei einem Mikroprozessor entscheidend?', 5, '[{"text": "Taktfrequenz", "correct": true, "because": "Bestimmt Geschwindigkeit"}, {"text": "Anzahl der Kerne", "correct": true, "because": "Fördert Multitasking"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein Mikroprozessor führt Befehle aus. b) Er enthält immer eine GPU. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "GPU optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um einen Mikroprozessor zu bewerten?', 4, '[{"text": "Leistungsdaten", "correct": false, "because": "Bestimmen Effizienz"}, {"text": "Kompatibilität", "correct": false, "because": "Sichert Funktion"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Mikroprozessor immer für alle Systeme kompatibel?', 2, '[{"text": "Nein", "correct": true, "because": "Sockelabhängig"}, {"text": "Ja", "correct": false, "because": "Zu vereinfacht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein moderner Mikroprozessor?', 4, '[{"text": "Hohe Geschwindigkeit", "correct": true, "because": "Verbessert Leistung"}, {"text": "Multitasking", "correct": true, "because": "Mehrere Kerne"}, {"text": "Schnellere Projekte", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Mikroprozessor immer eine GPU enthält. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "GPU optional"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um einen Mikroprozessor für ein System auszuwählen?', 3, '[{"text": "Taktfrequenz", "correct": true, "because": "Bestimmt Leistung"}, {"text": "Günstigster Preis", "correct": false, "because": "Leistung wichtiger"}, {"text": "Bunte Optik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Mikroprozessor hat mehrere Kerne. b) Er ist immer unabhängig von RAM.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "RAM wird benötigt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei einem Mikroprozessor?', 5, '[{"text": "Cache-Größe", "correct": true, "because": "Beeinflusst Geschwindigkeit"}, {"text": "Befehlssatz", "correct": true, "because": "Definiert Funktionen"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich einen Mikroprozessor auswähle?', 3, '[{"text": "Leistungsaufnahme", "correct": false, "because": "Bestimmt Effizienz"}, {"text": "Kernanzahl", "correct": false, "because": "Fördert Multitasking"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein Mikroprozessor ohne RAM arbeiten?', 3, '[{"text": "Nein", "correct": true, "because": "RAM für Daten nötig"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Mikroprozessor nur für PCs genutzt wird?', 2, '[{"text": "Nein", "correct": true, "because": "Auch in Geräten"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für einen Mikroprozessor?', 4, '[{"text": "Rechenleistung", "correct": true, "because": "Bestimmt Effizienz"}, {"text": "Schnellste Montage", "correct": false, "because": "Leistung zählt"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]');
